 public SessionOrchestrationRequest { Require.nonNull(requestId,"OrchestrationRequestId");Require.nonNull(sessionId,"LearningSessionId");Require.nonNull(sessionVersion,"SessionVersion");Require.nonNull(studentId,"StudentId");Require.nonNull(currentNodeId,"NodeId");Require.nonNull(attemptId,"ExerciseAttemptId");Require.nonNull(assessmentResultId,"AssessmentResultId");Require.nonNull(graphVersion,"GraphVersion");Require.nonNull(studentModelVersion,"StudentModelVersion");Require.nonNull(policySetVersion,"PolicySetVersion");Require.nonNull(correlationId,"CorrelationId");Require.nonNull(causationId,"CausationId"); }
